// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, MatrixTriangle, TransposeOperation, DiagonalType } from '@stdlib/types/blas';
import { Complex128Array } from '@stdlib/types/array';

/**
* Interface describing `ztbsv`.
*/
interface Routine {
	/**
	* Solves one of the systems of equations `A*x = b` or `A^T*x = b` or `x = A^H*x` where `b` and `x` are `N` element vectors and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular band matrix, with ( `K` + 1 ) diagonals.
	*
	* @param order - storage layout
	* @param uplo - specifies whether `A` is an upper or lower triangular matrix
	* @param trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
	* @param diag - specifies whether `A` has a unit diagonal
	* @param N - number of elements along each dimension in the matrix `A`
	* @param K - number of super-diagonals or sub-diagonals of the matrix `A`
	* @param A - input matrix
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param x - input vector
	* @param strideX - stride length for `x`
	* @returns `x`
	*
	* @example
	* var Complex128Array = require( '@stdlib/array/complex128' );
	*
	* var A = new Complex128Array( [ 0.0, 0.0, 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0, 5.0, 5.0 ] );
	* var x = new Complex128Array( [ 0.0, 2.0, 0.0, 16.0, 0.0, 46.0 ] );
	*
	* ztbsv( 'row-major', 'lower', 'no-transpose', 'non-unit', 3, 1, A, 2, x, 1 );
	* // x => <Complex128Array>[ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ]
	*/
	( order: Layout, uplo: MatrixTriangle, trans: TransposeOperation, diag: DiagonalType, N: number, K: number, A: Complex128Array, LDA: number, x: Complex128Array, strideX: number ): Complex128Array;

	/**
	* Solves one of the systems of equations `A*x = b` or `A^T*x = b` or `x = A^H*x`, using alternative indexing semantics and where `x` is an `N` element vector and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular band matrix, with (`K` + 1) diagonals.
	*
	* @param uplo - specifies whether `A` is an upper or lower triangular matrix
	* @param trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
	* @param diag - specifies whether `A` has a unit diagonal
	* @param N - number of elements along each dimension in the matrix `A`
	* @param K - number of super-diagonals or sub-diagonals of the matrix `A`
	* @param A - input matrix
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param x - input vector
	* @param strideX - stride length for `x`
	* @param offsetX - starting index for `x`
	* @returns `x`
	*
	* @example
	* var Complex128Array = require( '@stdlib/array/complex128' );
	*
	* var A = new Complex128Array( [ 0.0, 0.0, 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0, 5.0, 5.0 ] );
	* var x = new Complex128Array( [ 0.0, 2.0, 0.0, 16.0, 0.0, 46.0 ] );
	*
	* ztbsv.ndarray( 'lower', 'no-transpose', 'non-unit', 3, 1, A, 2, 1, 0, x, 1, 0 );
	* // x => <Complex128Array>[ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ]
	*/
	ndarray( uplo: MatrixTriangle, trans: TransposeOperation, diag: DiagonalType, N: number, K: number, A: Complex128Array, strideA1: number, strideA2: number, offsetA: number, x: Complex128Array, strideX: number, offsetX: number ): Complex128Array;
}

/**
* Solves one of the systems of equations `A*x = b` or `A^T*x = b` or `x = A^H*x` where `b` and `x` are `N` element vectors and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular band matrix, with ( `K` + 1 ) diagonals.
*
* @param order - storage layout
* @param uplo - specifies whether `A` is an upper or lower triangular matrix
* @param trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param diag - specifies whether `A` has a unit diagonal
* @param N - number of elements along each dimension in the matrix `A`
* @param K - number of super-diagonals or sub-diagonals of the matrix `A`
* @param A - input matrix
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param x - input vector
* @param strideX - stride length for `x`
* @returns `x`
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var A = new Complex128Array( [ 0.0, 0.0, 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0, 5.0, 5.0 ] );
* var x = new Complex128Array( [ 0.0, 2.0, 0.0, 16.0, 0.0, 46.0 ] );
*
* ztbsv( 'row-major', 'lower', 'no-transpose', 'non-unit', 3, 1, A, 2, x, 1 );
* // x => <Complex128Array>[ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ]
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var A = new Complex128Array( [ 0.0, 0.0, 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0, 5.0, 5.0 ] );
* var x = new Complex128Array( [ 0.0, 2.0, 0.0, 16.0, 0.0, 46.0 ] );
*
* ztbsv.ndarray( 'lower', 'no-transpose', 'non-unit', 3, 1, A, 2, 1, 0, x, 1, 0 );
* // x => <Complex128Array>[ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ]
*/
declare var ztbsv: Routine;


// EXPORTS //

export = ztbsv;
